import SwiftUI

struct PaneCardView: View {
    let title: String
    let isFocused: Bool
    let hasNotification: Bool
    let isTranscribing: Bool
    let transcript: String
    var terminalText: String = ""
    var contentScale: CGFloat = 1.0
    var isBrowser: Bool = false
    var browserURL: String = ""
    var hasFullHistory: Bool = false
    var isLoadingHistory: Bool = false
    var onLoadHistory: (() -> Void)?

    @State private var notificationPulse = false

    var body: some View {
        ZStack {
            // Glass background
            RoundedRectangle(cornerRadius: 12)
                .fill(.ultraThinMaterial.opacity(isFocused ? 0.4 : 0.2))
                .environment(\.colorScheme, .dark)

            // Notification pulse ring
            if hasNotification {
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.orange, lineWidth: 2.5)
                    .opacity(notificationPulse ? 0.4 : 1.0)
                    .animation(
                        .easeInOut(duration: 1.2).repeatForever(autoreverses: true),
                        value: notificationPulse
                    )
                    .onAppear { notificationPulse = true }
                    .onDisappear { notificationPulse = false }
            }

            // Focus glow border
            RoundedRectangle(cornerRadius: 12)
                .stroke(borderColor, lineWidth: isFocused ? 1.5 : 0.5)

            // Content
            VStack(spacing: 0) {
                // Title bar
                titleBar

                // Body area
                ZStack(alignment: .topLeading) {
                    if isTranscribing && !transcript.isEmpty {
                        Text(transcript)
                            .font(.system(size: 11, weight: .regular, design: .monospaced))
                            .foregroundColor(.green.opacity(0.8))
                            .lineLimit(4)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(.horizontal, 10)
                            .padding(.top, 8)
                    } else if isBrowser {
                        VStack(spacing: 8) {
                            Image(systemName: "globe")
                                .font(.system(size: isFocused ? 28 : 16))
                                .foregroundStyle(.white.opacity(0.2))
                            if !browserURL.isEmpty {
                                Text(browserURL
                                    .replacingOccurrences(of: "https://", with: "")
                                    .replacingOccurrences(of: "http://", with: ""))
                                    .font(.system(size: isFocused ? 10 : 7, design: .monospaced))
                                    .foregroundStyle(.white.opacity(0.4))
                                    .lineLimit(2)
                                    .multilineTextAlignment(.center)
                            }
                            if !title.isEmpty {
                                Text(title)
                                    .font(.system(size: isFocused ? 9 : 7, weight: .medium))
                                    .foregroundStyle(.white.opacity(0.3))
                                    .lineLimit(1)
                            }
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    } else if !terminalText.isEmpty {
                        terminalContentView
                    } else if !isBrowser {
                        // Loading state for terminals before content arrives
                        VStack(spacing: 10) {
                            ProgressView()
                                .scaleEffect(0.7)
                                .tint(.white.opacity(0.3))
                            Text("Loading…")
                                .font(.system(size: 9, weight: .medium, design: .monospaced))
                                .foregroundStyle(.white.opacity(0.2))
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
            }
        }
        .shadow(color: isFocused ? .white.opacity(0.08) : .clear, radius: 12)
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .fill(isTranscribing ? Color.red.opacity(0.03) : .clear)
        )
    }

    // MARK: - Terminal content

    private var terminalContentView: some View {
        // UITextView-backed so output is selectable (copy) and URLs are tappable.
        TerminalTextView(
            text: terminalText,
            fontSize: (isFocused ? 9 : 7) * contentScale,
            textOpacity: isFocused ? 0.85 : 0.5
        )
        // Floating "Load history" chip on focused cards, over the scrolling text.
        .overlay(alignment: .top) {
            if isFocused && !hasFullHistory {
                loadHistoryButton
                    .padding(.top, 4)
            }
        }
    }

    private var loadHistoryButton: some View {
        Button {
            onLoadHistory?()
        } label: {
            HStack(spacing: 6) {
                if isLoadingHistory {
                    ProgressView()
                        .scaleEffect(0.5)
                        .tint(.white.opacity(0.4))
                } else {
                    Image(systemName: "arrow.up.circle")
                        .font(.system(size: 10))
                }
                Text(isLoadingHistory ? "Loading…" : "Load history")
                    .font(.system(size: 8, weight: .medium, design: .monospaced))
            }
            .foregroundStyle(.white.opacity(0.5))
            .padding(.horizontal, 12)
            .padding(.vertical, 5)
            .background(
                Capsule().fill(.ultraThinMaterial).environment(\.colorScheme, .dark)
            )
        }
        .disabled(isLoadingHistory)
    }

    // MARK: - Title bar

    private var titleBar: some View {
        HStack(spacing: 6) {
            // Surface type icon
            Image(systemName: isBrowser ? "globe" : "terminal")
                .font(.system(size: 9, weight: .medium))
                .foregroundStyle(isFocused ? .white.opacity(0.5) : .white.opacity(0.2))

            // Title
            Text(title.isEmpty ? "untitled" : title)
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(isFocused ? .white.opacity(0.7) : .white.opacity(0.3))
                .lineLimit(1)
                .truncationMode(.middle)

            Spacer()

            // Recording indicator
            if isTranscribing {
                HStack(spacing: 4) {
                    Circle()
                        .fill(Color.red)
                        .frame(width: 6, height: 6)
                        .shadow(color: .red.opacity(0.6), radius: 3)
                    Text("REC")
                        .font(.system(size: 8, weight: .bold, design: .monospaced))
                        .foregroundStyle(.red.opacity(0.8))
                }
            }
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .background(
            Rectangle()
                .fill(isFocused ? Color.white.opacity(0.06) : Color.white.opacity(0.02))
        )
        // Top corners only
        .clipShape(
            UnevenRoundedRectangle(
                topLeadingRadius: 12,
                bottomLeadingRadius: 0,
                bottomTrailingRadius: 0,
                topTrailingRadius: 12
            )
        )
    }

    private var borderColor: Color {
        if hasNotification { return Color.orange.opacity(0.6) }
        if isFocused { return Color.white.opacity(0.5) }
        return Color.white.opacity(0.08)
    }
}

import Foundation
import Combine
import UserNotifications

@MainActor
final class AppState: ObservableObject {
    @Published var connectionStatus: ConnectionStatus = .disconnected
    @Published var notifications: [BridgeNotification] = []
    @Published var workspaces: [Workspace] = []
    @Published var currentWorkspaceID: String?
    @Published var surfaces: [Surface] = []
    @Published var panes: [Pane] = []
    @Published var isPairingPresented = false
    // Tracks the last surface explicitly focused by the user; used when surface.list
    // doesn't return is_focused and pane.list is unavailable.
    @Published private(set) var localFocusedSurfaceID: String?
    @Published var surfaceContent: [String: String] = [:]
    @Published var browserURLs: [String: String] = [:]

    private var lastFocusedSurface: [String: String] = [:]
    private let pairingStore = PairingStore()
    private var client: BridgeClient?
    private var discovery: BridgeDiscovery?

    init() {
        startDiscovery()
        connectIfPaired()
        requestNotificationPermission()
    }

    private func requestNotificationPermission() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { granted, _ in
            print("[Notification] push permission: \(granted)")
        }
    }

    private func scheduleLocalNotification(_ n: BridgeNotification) {
        let center = UNUserNotificationCenter.current()
        let content = UNMutableNotificationContent()
        content.title = n.title
        if let subtitle = n.subtitle { content.subtitle = subtitle }
        if let body = n.body { content.body = body }
        content.sound = .default

        let request = UNNotificationRequest(
            identifier: n.id,
            content: content,
            trigger: nil // deliver immediately
        )
        center.add(request)
    }

    // MARK: - Pairing

    func handlePairingURL(_ url: URL) {
        guard url.scheme == "cmux-bridge",
              url.host == "pair",
              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              let host = components.queryItems?.first(where: { $0.name == "host" })?.value,
              let portStr = components.queryItems?.first(where: { $0.name == "port" })?.value,
              let port = Int(portStr),
              let token = components.queryItems?.first(where: { $0.name == "token" })?.value
        else { return }

        let tailscaleHost = components.queryItems?.first(where: { $0.name == "tailscale_host" })?.value
        let credentials = PairingCredentials(host: host, port: port, token: token, tailscaleHost: tailscaleHost)
        try? pairingStore.save(credentials)
        connect(to: credentials)
        isPairingPresented = false
    }

    func unpair() {
        client?.disconnect()
        client = nil
        try? pairingStore.delete()
        connectionStatus = .disconnected
        notifications = []
        workspaces = []
        surfaces = []
        panes = []

import Foundation

// MARK: - Message types

enum BridgeMessage {
    case connected(ConnectedPayload)
    case notificationCreated(BridgeNotification)
    case notificationCleared
    case cmuxConnected
    case cmuxDisconnected
    case commandResponse(CommandResponse)
}

struct ConnectedPayload: Decodable {
    let bridgeVersion: String
    let cmuxConnected: Bool
    let protocolVersion: Int

    enum CodingKeys: String, CodingKey {
        case bridgeVersion = "bridge_version"
        case cmuxConnected = "cmux_connected"
        case protocolVersion = "protocol_version"
    }
}

struct CommandResponse {
    let id: String
    let ok: Bool
    let result: [String: Any]
    let error: CommandError?
}

struct CommandError {
    let code: String
    let message: String
}

// MARK: - Delegate

protocol BridgeClientDelegate: AnyObject {
    @MainActor func clientDidConnect(_ client: BridgeClient)
    @MainActor func clientDidDisconnect(_ client: BridgeClient, error: Error?)
    @MainActor func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage)
}

// MARK: - Client

final class BridgeClient: NSObject {
    let credentials: PairingCredentials
    weak var delegate: BridgeClientDelegate?

    private var task: URLSessionWebSocketTask?
    private var session: URLSession?
    private var completions: [String: ([String: Any]) -> Void] = [:]
    // `completions` is written from the caller (main actor) and read from the
    // URLSession receive queue, so all access must be serialized.
    private let completionsLock = NSLock()
    private var reconnectTask: Task<Void, Never>?
    private var shouldReconnect = true
    private var backoff: TimeInterval = 1

    init(credentials: PairingCredentials) {
        self.credentials = credentials
    }

    // MARK: - Public API

    func connect() {
        shouldReconnect = true
        startConnection()
    }

    func disconnect() {
        shouldReconnect = false
        reconnectTask?.cancel()
        task?.cancel(with: .normalClosure, reason: nil)
        task = nil
    }

    func send(
        method: String,
        params: [String: Any],
        completion: (([String: Any]) -> Void)? = nil
    ) {
        let id = UUID().uuidString
        let payload: [String: Any] = ["id": id, "method": method, "params": params]

        // Serialize the payload and confirm we have a live socket *before*
        // registering the completion, so a failed send can't leak a callback
        // that will never fire.
        guard let data = try? JSONSerialization.data(withJSONObject: payload),
              let text = String(data: data, encoding: .utf8),
              let task else { return }

        if let completion {
            completionsLock.lock()
            completions[id] = completion
            completionsLock.unlock()
        }

        task.send(.string(text)) { [weak self] error in
            guard error != nil, let self else { return }
            // The send failed — drop the pending completion so callers that
            // chain follow-up work (refreshSurfaces, etc.) aren't stranded.
            self.completionsLock.lock()
            self.completions.removeValue(forKey: id)
            self.completionsLock.unlock()
        }
    }

    // MARK: - Private

    /// Whether to try the tailscale host on next connection attempt.
    private var useTailscale = false

    private func startConnection() {
        let host: String
        if useTailscale, let tsHost = credentials.tailscaleHost, !tsHost.isEmpty {
            host = tsHost
        } else {
            host = credentials.host
        }

        let urlString = "ws://\(host):\(credentials.port)/ws"
        guard let url = URL(string: urlString) else { return }

        var request = URLRequest(url: url)
        request.setValue("Bearer \(credentials.token)", forHTTPHeaderField: "Authorization")
        request.timeoutInterval = useTailscale ? 10 : 5

        let session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
        self.session = session
        let task = session.webSocketTask(with: request)
        self.task = task
        task.resume()
        receiveNext()
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            switch result {
            case .success(let message):
                self.handleMessage(message)
                self.receiveNext()
            case .failure:
                self.handleDisconnect(error: nil)
            }
        }
    }

    private func handleMessage(_ message: URLSessionWebSocketTask.Message) {
        guard case .string(let text) = message,
              let data = text.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return }

        let bridgeMessage = parse(json: json)
        Task { @MainActor in
            self.delegate?.clientDidReceiveMessage(self, message: bridgeMessage)
        }

        // Dispatch command responses to completions. Fire the completion for
        // ANY response carrying a matching id — even an `ok:true` reply with no
        // `result` payload — otherwise chained follow-up work never runs and
        // the UI silently goes stale.
        if let id = json["id"] as? String {
            completionsLock.lock()
            let completion = completions.removeValue(forKey: id)
            completionsLock.unlock()
            if let completion {
                let result = json["result"] as? [String: Any] ?? [:]
                Task { @MainActor in completion(result) }
            }
        }
    }

    private func parse(json: [String: Any]) -> BridgeMessage {
        let type = json["type"] as? String ?? ""
        let data = json["data"] as? [String: Any] ?? [:]

        switch type {
        case "connected":
            if let payloadData = try? JSONSerialization.data(withJSONObject: data),
               let payload = try? JSONDecoder().decode(ConnectedPayload.self, from: payloadData) {
                return .connected(payload)
            }
        case "notification.created":
            if let notifData = try? JSONSerialization.data(withJSONObject: data),
               let notif = try? JSONDecoder().decode(BridgeNotification.self, from: notifData) {
                return .notificationCreated(notif)
            }
        case "notification.cleared":
            return .notificationCleared
        case "cmux.connected":
            return .cmuxConnected
        case "cmux.disconnected":
            return .cmuxDisconnected
        default:
            break
        }

        // Command response envelope
        if let id = json["id"] as? String {
            let ok = json["ok"] as? Bool ?? false
            let result = json["result"] as? [String: Any] ?? [:]
            var cmdError: CommandError?
            if let errDict = json["error"] as? [String: Any] {
                cmdError = CommandError(
                    code: errDict["code"] as? String ?? "",
                    message: errDict["message"] as? String ?? ""
                )
            }
            return .commandResponse(CommandResponse(id: id, ok: ok, result: result, error: cmdError))
        }

        return .notificationCleared // fallback
    }

    private func handleDisconnect(error: Error?) {
        task = nil
        // Drop any in-flight completions; their responses will never arrive.
        // A fresh connect re-issues refreshWorkspaces/Surfaces from scratch.
        completionsLock.lock()
        completions.removeAll()
        completionsLock.unlock()
        Task { @MainActor in
            self.delegate?.clientDidDisconnect(self, error: error)
        }
        guard shouldReconnect else { return }
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        let delay = backoff
        backoff = min(backoff * 2, 30)

        // Alternate between LAN and Tailscale on each retry
        if credentials.tailscaleHost != nil {
            useTailscale.toggle()
        }

        reconnectTask = Task {
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard !Task.isCancelled, self.shouldReconnect else { return }
            self.startConnection()
        }
    }
}

// MARK: - URLSessionWebSocketDelegate

extension BridgeClient: URLSessionWebSocketDelegate {
    func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didOpenWithProtocol protocol: String?
    ) {
        backoff = 1
        useTailscale = false // Reset — LAN worked, prefer it next time
        Task { @MainActor in
            self.delegate?.clientDidConnect(self)
        }
    }

    func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didCloseWith closeCode: URLSessionWebSocketTask.CloseCode,
        reason: Data?
    ) {
        handleDisconnect(error: nil)
    }
}

